function sheetsView(){const s=sheet();sheetId=s.id;const value=s.cells[cell]?.raw||'';return'<section class="panel"><div class="toolbar"><h1>高级表格</h1><span class="badge">原型增强</span><button data-act="undo"'+(!db.undo.length?' disabled':'')+'>撤销</button><button data-act="redo"'+(!db.redo.length?' disabled':'')+'>重做</button><button data-act="export" class="push">导出工作台备份</button><button data-act="import">导入备份</button></div><div class="toolbar"><label>工作表名称 <input aria-label="工作表名称" data-sheet-name value="'+esc(s.name)+'"></label><button data-act="rename">重命名</button><button data-act="add-sheet">添加工作表</button><button data-act="delete-sheet" class="danger">删除工作表</button><label>行数 <input aria-label="表格行数" type="number" min="1" max="100" data-size="rows" value="'+s.rows+'"></label><label>列数 <input aria-label="表格列数" type="number" min="1" max="40" data-size="cols" value="'+s.cols+'"></label><button data-act="resize">调整尺寸</button></div><div class="formula-bar"><input aria-label="起始单元格" data-range="start" value="'+esc(cell)+'"><span>至</span><input aria-label="结束单元格" data-range="end" value="'+esc(end)+'"><button data-act="range">选择区域</button><input aria-label="单元格内容或公式" data-formula value="'+esc(value)+'"><button data-act="apply" class="primary">应用内容</button></div><div class="toolbar"><button data-act="merge">合并选区</button><button data-act="split">拆分单元格</button><button data-act="print-preview">打印预览</button><span class="muted">Shift＋点击选择矩形区域。拆分会恢复各单元格原内容。</span></div><div class="table-scroll">'+grid(s)+'</div><div class="sheet-names">'+db.sheets.map(x=>'<button data-sheet-id="'+esc(x.id)+'" class="'+(x.id===s.id?'active':'')+'">'+esc(x.name)+'</button>').join('')+'</div><details><summary>公式与合并规则</summary><p>跨表：<code>=SUM(\'明细\'!C2:C3)</code>；支持四则、幂、比较、SUM、AVERAGE、MIN、MAX、COUNT、ROUND、ABS、IF、IFERROR。除零、循环、失效引用和非数字运算会显示错误，不变成0。不执行JavaScript。</p><p>合并保留所有原始内容，只显示左上角；跨表引用被覆盖单元格仍读取其原值。重命名会同步公式引用；删除表后引用显示#REF!。缩小尺寸若将丢失非空数据会被拦截。</p></details></section>';}
